from playwright.sync_api import sync_playwright
URL='http://127.0.0.1:28494'
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True);ctx=browser.new_context();page=ctx.new_page();page.goto(URL);page.locator('#newDialog[open]').wait_for();page.locator('#newName').fill('exit snapshot test');page.get_by_role('button',name='创建',exact=True).click();page.wait_for_function("document.querySelector('#workflowStatus')?.textContent.includes('待开始')");page.get_by_role('button',name='进入人工修订阶段').click();page.wait_for_function("document.querySelector('#workflowStatus')?.textContent.includes('人工修订')");page.get_by_role('button',name='进入人工修订模式').click();page.wait_for_function("document.querySelector('#workflowModeState')?.textContent.includes('已进入')");pid=page.evaluate('paperpilot.current.project.id');page.locator('#editor').fill('原先审阅的草稿');page.wait_for_function("document.querySelector('#workflowModeState')?.textContent.includes('1 项可恢复草稿')");page.get_by_role('button',name='退出人工修订模式').click();page.locator('#workflowDecisionDialog[open]').wait_for();assert '原先审阅的草稿' in page.locator('#workflowDecisionDescription').inner_text()
 draft=ctx.request.get(f'{URL}/api/projects/{pid}/human-revision/drafts').json()[0];changed={'target_kind':draft['target_kind'],'target_path':draft['target_path'],'base_version':draft['base_version'],'content':'其他页面更新的草稿','expected_draft_updated_at':draft['updated_at']};assert ctx.request.post(f'{URL}/api/projects/{pid}/human-revision/drafts',data=changed).ok
 page.locator('#workflowDecisionDialog').get_by_role('button',name='放弃草稿').click();page.wait_for_function("document.querySelector('#workflowAnnouncement').textContent.includes('草稿已新增、删除或更新')");assert ctx.request.get(f'{URL}/api/projects/{pid}/human-revision/drafts').json()[0]['content']=='其他页面更新的草稿';assert page.get_by_role('button',name='退出人工修订模式').is_visible()
 page.get_by_role('button',name='退出人工修订模式').click();page.locator('#workflowDecisionDialog[open]').wait_for();assert '其他页面更新的草稿' in page.locator('#workflowDecisionDescription').inner_text();page.locator('#workflowDecisionDialog').get_by_role('button',name='保留为草稿').click();page.wait_for_function("document.querySelector('#workflowAnnouncement').textContent.includes('已退出人工修订模式')");assert ctx.request.get(f'{URL}/api/projects/{pid}/human-revision/drafts').json()[0]['content']=='其他页面更新的草稿';browser.close();print('dialog race rejected and retry reviewed latest draft')
